(function(){
  try{
    var b='https://liz04.com';
    try{ var s=String(source.get('lizhost')||''); if(s.length>6) b=s; }catch(e){}
    var ck='';
    try{ ck=String(java.getCookie(b,null)||''); }catch(e2){}
    var logged=(ck&&(ck.indexOf('token')>=0||ck.indexOf('litchi.session')>=0));
    if(!logged){ return result; }
    // 已登录：确保带 Authorization 头（如站点用 Bearer token）
    try{
      var hm=java.getHeaderMap();
      if(hm&&ck.indexOf('token')>=0){
        var tk=ck.match(/token=([^;]+)/);
        if(tk&&!hm.get('Authorization')) hm.put('Authorization','Bearer '+tk[1]);
      }
    }catch(e3){}
    return result;
  }catch(e4){ return result; }
})()

