                    </div>
                    <div class="right-controls">
                        <div class="line-selector">
                            <div class="selector-btn" id="lineBtn" title="选择线路">线路1 <i class="fas fa-chevron-down"></i></div>
                            <div class="selector-menu" id="lineMenu"></div>
                        </div>
                        <div class="quality-selector">
                            <div class="selector-btn" id="qualityBtn" title="选择清晰度">默认 <i class="fas fa-chevron-down"></i></div>
                            <div class="selector-menu" id="qualityMenu"></div>
                        </div>
                        <button class="control-btn" id="fullscreenBtn" title="全屏">
                            <i class="fas fa-expand"></i>
                        </button>
                    </div>
